import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.LongSupplier;

public class Solution {
    enum Tipo { A, CNAME, NXDOMAIN }

    /** Uma resposta do servidor autoritativo para um nome: um endereço (A), um alias (CNAME) ou "não existe". */
    record Resposta(Tipo tipo, List<String> enderecos, String alvo, long ttl) {
        static Resposta a(long ttlSegundos, String... enderecos) {
            return new Resposta(Tipo.A, List.of(enderecos), null, ttlSegundos);
        }

        static Resposta cname(long ttlSegundos, String alvo) {
            return new Resposta(Tipo.CNAME, List.of(), alvo, ttlSegundos);
        }

        /** O ttl aqui é o TTL negativo (do SOA): por quanto tempo vale lembrar que o nome não existe. */
        static Resposta nxdomain(long ttlNegativoSegundos) {
            return new Resposta(Tipo.NXDOMAIN, List.of(), null, ttlNegativoSegundos);
        }
    }

    /** A rede, do ponto de vista do resolvedor: cada chamada é uma consulta de verdade. */
    interface Autoritativo {
        Resposta consultar(String nome);
    }

    enum Status { OK, NXDOMAIN, LACO, CADEIA_LONGA }

    /** Resultado de resolver(): cadeia de nomes percorrida e o menor TTL restante entre as entradas usadas. */
    record Resolucao(Status status, List<String> enderecos, List<String> cadeia, long ttlRestante) {}

    static final class ResolvedorDns {
        private record Entrada(Resposta resposta, long expiraEm) {}

        private final Autoritativo autoritativo;
        private final LongSupplier relogio;
        private final int maxSaltos;
        private final Map<String, Entrada> cache = new HashMap<>();   // nome -> última resposta guardada
        private int consultas = 0;

        ResolvedorDns(Autoritativo autoritativo, LongSupplier relogioMs, int maxSaltos) {
            if (autoritativo == null || relogioMs == null) throw new IllegalArgumentException("dependência nula");
            if (maxSaltos < 1) throw new IllegalArgumentException("maxSaltos precisa ser >= 1");
            this.autoritativo = autoritativo;
            this.relogio = relogioMs;
            this.maxSaltos = maxSaltos;
        }

        int consultas() { return consultas; }

        Resolucao resolver(String nome) {
            String atual = normalizar(nome);
            List<String> cadeia = new ArrayList<>();
            Set<String> vistos = new HashSet<>();
            long menorTtl = Long.MAX_VALUE;
            int saltos = 0;

            while (true) {
                cadeia.add(atual);
                if (!vistos.add(atual)) return new Resolucao(Status.LACO, List.of(), cadeia, menorTtl == Long.MAX_VALUE ? 0 : menorTtl);

                long agora = relogio.getAsLong();
                Entrada e = cache.get(atual);
                if (e == null || agora >= e.expiraEm()) {
                    Resposta r = autoritativo.consultar(atual);
                    consultas++;
                    e = new Entrada(r, agora + Math.max(r.ttl(), 0) * 1000);
                    if (r.ttl() > 0) cache.put(atual, e); else cache.remove(atual);
                }
                long restante = Math.max(0, (e.expiraEm() - agora + 999) / 1000);   // arredonda para cima: válido nunca mostra 0
                menorTtl = Math.min(menorTtl, restante);

                switch (e.resposta().tipo()) {
                    case A -> {
                        return new Resolucao(Status.OK, e.resposta().enderecos(), cadeia, menorTtl);
                    }
                    case NXDOMAIN -> {
                        return new Resolucao(Status.NXDOMAIN, List.of(), cadeia, menorTtl);
                    }
                    case CNAME -> {
                        if (saltos == maxSaltos) return new Resolucao(Status.CADEIA_LONGA, List.of(), cadeia, menorTtl);
                        saltos++;
                        atual = normalizar(e.resposta().alvo());
                    }
                }
            }
        }

        static String normalizar(String nome) {
            if (nome == null) throw new IllegalArgumentException("nome nulo");
            String n = nome.trim().toLowerCase();
            if (n.endsWith(".")) n = n.substring(0, n.length() - 1);
            if (n.isEmpty() || n.length() > 253) throw new IllegalArgumentException("nome inválido: " + nome);
            for (String label : n.split("[.]", -1)) {
                if (label.isEmpty() || label.length() > 63) throw new IllegalArgumentException("label inválido em: " + nome);
            }
            return n;
        }
    }
}

