import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.LongSupplier;

class SolutionTest {
    static final class Relogio implements LongSupplier {
        long agora = 0;
        @Override public long getAsLong() { return agora; }
        Relogio segundos(long s) { agora = s * 1000; return this; }
    }

    /** Servidor autoritativo de mentira: uma tabela que pode mudar, e um registro das consultas. */
    static final class Zona implements Solution.Autoritativo {
        final Map<String, Solution.Resposta> registros = new HashMap<>();
        final List<String> consultas = new ArrayList<>();
        RuntimeException falha;

        Zona com(String nome, Solution.Resposta r) { registros.put(nome, r); return this; }

        @Override public Solution.Resposta consultar(String nome) {
            consultas.add(nome);
            if (falha != null) throw falha;
            return registros.getOrDefault(nome, Solution.Resposta.nxdomain(60));
        }
    }

    static Zona loja() {
        return new Zona()
            .com("www.loja.com.br", Solution.Resposta.cname(600, "loja.cdn-exemplo.net"))
            .com("loja.cdn-exemplo.net", Solution.Resposta.cname(300, "edge.cdn-exemplo.net."))
            .com("edge.cdn-exemplo.net", Solution.Resposta.a(60, "198.51.100.50", "198.51.100.51"))
            .com("loja.com.br", Solution.Resposta.a(300, "203.0.113.10"));
    }

    static Solution.ResolvedorDns resolvedor(Zona z, Relogio t) { return new Solution.ResolvedorDns(z, t, 8); }

    // ---------- resolução simples e cadeia de CNAME ----------

    @Test void registroAResolveDireto() {
        Zona z = loja();
        Solution.Resolucao r = resolvedor(z, new Relogio()).resolver("loja.com.br");
        assertEquals(Solution.Status.OK, r.status());
        assertEquals(List.of("203.0.113.10"), r.enderecos());
        assertEquals(List.of("loja.com.br"), r.cadeia());
        assertEquals(300, r.ttlRestante());
        assertEquals(List.of("loja.com.br"), z.consultas);
    }

    @Test void seguePelaCadeiaDeCname() {
        Zona z = loja();
        Solution.Resolucao r = resolvedor(z, new Relogio()).resolver("www.loja.com.br");
        assertEquals(Solution.Status.OK, r.status());
        assertEquals(List.of("198.51.100.50", "198.51.100.51"), r.enderecos(), "todos os A, na ordem da zona");
        assertEquals(List.of("www.loja.com.br", "loja.cdn-exemplo.net", "edge.cdn-exemplo.net"), r.cadeia());
        assertEquals(List.of("www.loja.com.br", "loja.cdn-exemplo.net", "edge.cdn-exemplo.net"), z.consultas);
    }

    @Test void ttlDaRespostaEOMenorDaCadeia() {
        Solution.Resolucao r = resolvedor(loja(), new Relogio()).resolver("www.loja.com.br");
        assertEquals(60, r.ttlRestante(), "CNAME 600, CNAME 300 e A 60: vale o 60");
    }

    @Test void nomesSaoNormalizados() {
        Zona z = loja();
        Solution.ResolvedorDns d = resolvedor(z, new Relogio());
        Solution.Resolucao r = d.resolver("  WWW.Loja.COM.br. ");
        assertEquals(Solution.Status.OK, r.status());
        assertEquals("www.loja.com.br", r.cadeia().get(0));
        d.resolver("www.loja.com.br");
        assertEquals(3, z.consultas.size(), "a segunda forma do mesmo nome usa o cache");
    }

    // ---------- cache positivo e TTL ----------

    @Test void segundaConsultaVemDoCache() {
        Zona z = loja();
        Solution.ResolvedorDns d = resolvedor(z, new Relogio());
        d.resolver("www.loja.com.br");
        Solution.Resolucao r = d.resolver("www.loja.com.br");
        assertEquals(Solution.Status.OK, r.status());
        assertEquals(3, z.consultas.size());
        assertEquals(3, d.consultas());
    }

    @Test void ttlRestanteDiminuiComOTempo() {
        Relogio t = new Relogio();
        Solution.ResolvedorDns d = resolvedor(loja(), t);
        d.resolver("www.loja.com.br");
        t.segundos(20);
        assertEquals(40, d.resolver("www.loja.com.br").ttlRestante());
        t.segundos(59);
        assertEquals(1, d.resolver("www.loja.com.br").ttlRestante());
    }

    @Test void ttlRestanteArredondaParaCima() {
        Relogio t = new Relogio();
        Solution.ResolvedorDns d = resolvedor(loja(), t);
        d.resolver("www.loja.com.br");
        t.agora = 20_500;
        assertEquals(40, d.resolver("www.loja.com.br").ttlRestante(), "restam 39,5 s: mostra 40");
    }

    @Test void entradaExpiraExatamenteNoTtl() {
        Zona z = loja();
        Relogio t = new Relogio();
        Solution.ResolvedorDns d = resolvedor(z, t);
        d.resolver("loja.com.br");
        t.segundos(299);
        d.resolver("loja.com.br");
        assertEquals(1, z.consultas.size(), "aos 299 s ainda vale");
        t.segundos(300);
        d.resolver("loja.com.br");
        assertEquals(2, z.consultas.size(), "aos 300 s expirou");
    }

    @Test void soOQueExpirouEConsultadoDeNovo() {
        Zona z = loja();
        Relogio t = new Relogio();
        Solution.ResolvedorDns d = resolvedor(z, t);
        d.resolver("www.loja.com.br");
        z.consultas.clear();
        t.segundos(61);                         // o A (60 s) expirou; os CNAMEs (600 e 300 s) não
        Solution.Resolucao r = d.resolver("www.loja.com.br");
        assertEquals(Solution.Status.OK, r.status());
        assertEquals(List.of("edge.cdn-exemplo.net"), z.consultas, "só a ponta da cadeia é reconsultada");
        assertEquals(60, r.ttlRestante(), "o A novo trouxe 60 s; os CNAMEs ainda têm bem mais");
    }

    @Test void mudancaNaZonaSoApareceDepoisDoTtl() {
        Zona z = loja();
        Relogio t = new Relogio();
        Solution.ResolvedorDns d = resolvedor(z, t);
        d.resolver("loja.com.br");
        z.com("loja.com.br", Solution.Resposta.a(300, "203.0.113.99"));
        assertEquals(List.of("203.0.113.10"), d.resolver("loja.com.br").enderecos());
        t.segundos(300);
        assertEquals(List.of("203.0.113.99"), d.resolver("loja.com.br").enderecos());
    }

    @Test void ttlZeroNaoFicaEmCache() {
        Zona z = new Zona().com("a.exemplo.com", Solution.Resposta.a(0, "192.0.2.1"));
        Solution.ResolvedorDns d = resolvedor(z, new Relogio());
        Solution.Resolucao r = d.resolver("a.exemplo.com");
        assertEquals(List.of("192.0.2.1"), r.enderecos());
        assertEquals(0, r.ttlRestante());
        d.resolver("a.exemplo.com");
        assertEquals(2, z.consultas.size());
    }

    // ---------- cache negativo ----------

    @Test void nxdomainEntraNoCacheNegativo() {
        Zona z = loja();
        Relogio t = new Relogio();
        Solution.ResolvedorDns d = resolvedor(z, t);
        z.com("wwww.loja.com.br", Solution.Resposta.nxdomain(300));
        Solution.Resolucao r = d.resolver("wwww.loja.com.br");
        assertEquals(Solution.Status.NXDOMAIN, r.status());
        assertTrue(r.enderecos().isEmpty());
        assertEquals(300, r.ttlRestante());
        t.segundos(100);
        Solution.Resolucao r2 = d.resolver("wwww.loja.com.br");
        assertEquals(Solution.Status.NXDOMAIN, r2.status());
        assertEquals(200, r2.ttlRestante());
        assertEquals(1, z.consultas.size(), "o NXDOMAIN foi lembrado");
    }

    @Test void cacheNegativoExpiraEODnsPassaAEnxergarONomeNovo() {
        Zona z = loja();
        Relogio t = new Relogio();
        Solution.ResolvedorDns d = resolvedor(z, t);
        z.com("api.loja.com.br", Solution.Resposta.nxdomain(300));
        assertEquals(Solution.Status.NXDOMAIN, d.resolver("api.loja.com.br").status());
        z.com("api.loja.com.br", Solution.Resposta.a(60, "203.0.113.20"));      // o registro foi criado logo depois
        t.segundos(299);
        assertEquals(Solution.Status.NXDOMAIN, d.resolver("api.loja.com.br").status(), "ainda no cache negativo");
        t.segundos(300);
        Solution.Resolucao r = d.resolver("api.loja.com.br");
        assertEquals(Solution.Status.OK, r.status());
        assertEquals(List.of("203.0.113.20"), r.enderecos());
    }

    @Test void nxdomainNoFimDaCadeia() {
        Zona z = new Zona().com("a.exemplo.com", Solution.Resposta.cname(600, "b.exemplo.com")).com("b.exemplo.com", Solution.Resposta.nxdomain(120));
        Solution.ResolvedorDns d = resolvedor(z, new Relogio());
        Solution.Resolucao r = d.resolver("a.exemplo.com");
        assertEquals(Solution.Status.NXDOMAIN, r.status());
        assertEquals(List.of("a.exemplo.com", "b.exemplo.com"), r.cadeia());
        assertEquals(120, r.ttlRestante());
        d.resolver("a.exemplo.com");
        assertEquals(2, z.consultas.size(), "o CNAME e o NXDOMAIN do alvo ficaram em cache");
    }

    // ---------- laços e cadeias longas ----------

    @Test void cnameParaSiMesmoELaco() {
        Zona z = new Zona().com("a.exemplo.com", Solution.Resposta.cname(300, "a.exemplo.com"));
        Solution.Resolucao r = resolvedor(z, new Relogio()).resolver("a.exemplo.com");
        assertEquals(Solution.Status.LACO, r.status());
        assertEquals(List.of("a.exemplo.com", "a.exemplo.com"), r.cadeia());
        assertTrue(r.enderecos().isEmpty());
    }

    @Test void lacoEntreTresNomes() {
        Zona z = new Zona()
            .com("a.exemplo.com", Solution.Resposta.cname(300, "b.exemplo.com"))
            .com("b.exemplo.com", Solution.Resposta.cname(300, "c.exemplo.com"))
            .com("c.exemplo.com", Solution.Resposta.cname(300, "A.Exemplo.com."));
        Solution.ResolvedorDns d = resolvedor(z, new Relogio());
        Solution.Resolucao r = d.resolver("a.exemplo.com");
        assertEquals(Solution.Status.LACO, r.status());
        assertEquals(List.of("a.exemplo.com", "b.exemplo.com", "c.exemplo.com", "a.exemplo.com"), r.cadeia());
        assertEquals(300, r.ttlRestante());
    }

    @Test void lacoContinuaSendoDetectadoComTudoEmCache() {
        Zona z = new Zona()
            .com("a.exemplo.com", Solution.Resposta.cname(300, "b.exemplo.com"))
            .com("b.exemplo.com", Solution.Resposta.cname(300, "a.exemplo.com"));
        Solution.ResolvedorDns d = resolvedor(z, new Relogio());
        assertEquals(Solution.Status.LACO, d.resolver("a.exemplo.com").status());
        int antes = d.consultas();
        assertEquals(Solution.Status.LACO, d.resolver("b.exemplo.com").status());
        assertEquals(antes, d.consultas(), "nenhuma consulta nova: só cache");
    }

    @Test void cadeiaLongaDemaisEAbandonada() {
        Zona z = new Zona();
        for (int i = 0; i < 10; i++) z.com("n" + i + ".exemplo.com", Solution.Resposta.cname(300, "n" + (i + 1) + ".exemplo.com"));
        z.com("n10.exemplo.com", Solution.Resposta.a(300, "192.0.2.10"));
        Solution.Resolucao r = new Solution.ResolvedorDns(z, new Relogio(), 8).resolver("n0.exemplo.com");
        assertEquals(Solution.Status.CADEIA_LONGA, r.status());
        assertEquals(9, r.cadeia().size(), "n0 até n8: oito saltos seguidos e o nono nome ainda é CNAME");
    }

    @Test void exatamenteOMaximoDeSaltosAindaResolve() {
        Zona z = new Zona();
        for (int i = 0; i < 3; i++) z.com("n" + i + ".exemplo.com", Solution.Resposta.cname(300, "n" + (i + 1) + ".exemplo.com"));
        z.com("n3.exemplo.com", Solution.Resposta.a(300, "192.0.2.3"));
        assertEquals(Solution.Status.OK, new Solution.ResolvedorDns(z, new Relogio(), 3).resolver("n0.exemplo.com").status());
        assertEquals(Solution.Status.CADEIA_LONGA, new Solution.ResolvedorDns(z, new Relogio(), 2).resolver("n0.exemplo.com").status());
    }

    // ---------- falhas da rede e validação ----------

    @Test void falhaDoAutoritativoPropagaENaoContaminaOCache() {
        Zona z = loja();
        Solution.ResolvedorDns d = resolvedor(z, new Relogio());
        z.falha = new IllegalStateException("timeout");
        assertThrows(IllegalStateException.class, () -> d.resolver("loja.com.br"));
        z.falha = null;
        assertEquals(List.of("203.0.113.10"), d.resolver("loja.com.br").enderecos());
    }

    @Test void nomesInvalidos() {
        Solution.ResolvedorDns d = resolvedor(loja(), new Relogio());
        for (String ruim : new String[] {null, "", "   ", ".", "a..b", ".com", "x".repeat(64) + ".com", ("a".repeat(60) + ".").repeat(5) + "br"}) {
            assertThrows(IllegalArgumentException.class, () -> d.resolver(ruim), String.valueOf(ruim));
        }
        assertEquals(0, d.consultas());
    }

    @Test void argumentosDoConstrutor() {
        Zona z = loja();
        assertThrows(IllegalArgumentException.class, () -> new Solution.ResolvedorDns(null, new Relogio(), 8));
        assertThrows(IllegalArgumentException.class, () -> new Solution.ResolvedorDns(z, null, 8));
        assertThrows(IllegalArgumentException.class, () -> new Solution.ResolvedorDns(z, new Relogio(), 0));
    }
}
